import React from 'react';
import Skills from "./Skills";
import About from './About';
import Experience from './Experience';
import Navbar from '../components/NavBar.tsx';
import Home from './Home.tsx';
import Project from "./Project.jsx";
import useTabSwitcher from "../Hooks/useTabSwitcher.tsx";
import "../styles/scss-style/style.scss";
import '../styles/App.css';
const App = () => {

  useTabSwitcher();

  return (
    <>
      <div className='background_style'>
        <Navbar />

        <section className='section'>
          <section className="cards-container">
            <div className="card card--current papers" id="1">
              <Home />
            </div>
            <div className="card papers" id="2">
              <About />
            </div>
            <div className="card papers" id="3">
              <Skills />
            </div>
            <div className="card papers" id="4">
              <Experience />
            </div>
            <div className="card papers" id="5">
              <Project />
            </div>
            {/* <div className="card papers" id="5">
              <Contact />
            </div> */}
          </section>
        </section>
      </div>
    </>
  );
}

export default App;