import "animate.css";
 
import ExperienceData from "../Assets/Data/workExperience.json"
import "../styles/scss-style/TimeLine.scss";
const ExperienceList = () => {
  let workExperience = ExperienceData.workExperience;
 

  return (
    <>
      <div className="timeline">
        {workExperience.filter((_, index) => index !== 1).map((entry, index) => (
          <div key={index} class="entry">
            <div class="title-t">
              <h3 className="Title_Name">{entry.title}</h3>
              <p className="Role_name">   {entry.company.role} | {entry.company.name}</p>
            </div>
            <div class="body">
              <p className="Role_name">Voluptatibus veniam ea reprehenderit atque reiciendis non laborum adipisci ipsa pariatur omnis.</p>
              <ul>
                <li>Rerum sit libero possimus amet excepturi</li>
                <li>Exercitationem enim dolores sunt praesentium dolorum praesentium</li>
                <li>Modi aut dolores dignissimos sequi sit ut aliquid molestias deserunt illo</li>
              </ul>
            </div>
          </div>
        ))}
      </div>
    </>
  );
};

export default ExperienceList;
